# Problem 1
from datetime import datetime, timedelta

def to_min(t):
    h, m = map(int, t.split(':'))
    return h * 60 + m

def to_str(m):
    h = m // 60
    mi = m % 60
    return f"{h:02d}:{mi:02d}"

def subtract(base, busy):
    res = []
    for b_start, b_end in base:
        cur_start = b_start
        for s, e in sorted(busy):
            if e <= cur_start or s >= b_end:
                continue
            if s > cur_start:
                res.append((cur_start, s))
            cur_start = max(cur_start, e)
        if cur_start < b_end:
            res.append((cur_start, b_end))
    return res

def intersect(a, b):
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            res.append((s, e))
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

