people = {
    'Natalie': [],
    'David': [('11:30','12:00'), ('14:30','15:00')],
    'Douglas': [('09:30','10:00'), ('11:30','12:00'), ('13:00','13:30'), ('14:30','15:00')],
    'Ralph': [('09:00','09:30'), ('10:00','11:00'), ('11:30','12:30'), ('13:30','15:00'), ('15:30','16:00'), ('16:30','17:00')],
    'Jordan': [('09:00','10:00'), ('12:00','12:30'), ('13:00','13:30'), ('14:30','15:00'), ('15:30','17:00')],
}

# add preference: David not before 14:00
people['David'].append(('09:00','14:00'))

duration = 30  # minutes
common = work
for busy in people.values():
    busy_min = [(to_min(s), to_min(e)) for s, e in busy]
    free = subtract(work, busy_min)
    common = intersect(common, free)

for start, end in common:
    if end - start >= duration:
        ans_start = start
        ans_end = start + duration
        print(['Monday', to_str(ans_start), to_str(ans_end)])
        break

