# Problem 1
from datetime import datetime, timedelta

def to_min(t):
    h, m = map(int, t.split(':'))
    return h * 60 + m

def to_str(m):
    return f"{m//60:02d}:{m%60:02d}"

work_start = to_min('09:00')
work_end = to_min('17:00')
duration = 60

busy = {
    'Monday': [
        (to_min('11:30'), to_min('12:00')),
        (to_min('14:30'), to_min('15:00')),
        (to_min('09:30'), to_min('11:00')),
        (to_min('11:30'), to_min('12:00')),
        (to_min('12:30'), to_min('13:30')),
        (to_min('14:30'), to_min('16:30')),
    ]
}

def merge(intervals):
    intervals.sort()
    merged = []
    for s, e in intervals:
        if not merged or s > merged[-1][1]:
            merged.append([s, e])
        else:
            merged[-1][1] = max(merged[-1][1], e)
    return merged

def find_slot(day):
    merged = merge(busy.get(day, []))
    prev_end = work_start
    for s, e in merged:
        if s - prev_end >= duration:
            return prev_end, prev_end + duration
        prev_end = max(prev_end, e)
    if work_end - prev_end >= duration:
        return prev_end, prev_end + duration
    return None

slot = find_slot('Monday')
print(['Monday', to_str(slot[0]), to_str(slot[1])])

