    return h * 60 + m

def to_str(m):
    return f"{m//60:02d}:{m%60:02d}"

def merge(intervals):
    intervals = sorted(intervals)
    merged = []
    for s, e in intervals:
        if not merged or s > merged[-1][1]:
            merged.append([s, e])
        else:
            merged[-1][1] = max(merged[-1][1], e)
    return merged

def complement(busy, work_start, work_end):
    busy = merge(busy)
    free = []
    prev_end = work_start
    for s, e in busy:
        if s > prev_end:
            free.append([prev_end, s])
        prev_end = max(prev_end, e)
    if prev_end < work_end:
        free.append([prev_end, work_end])
    return free

def intersect_two(a, b):
    i, j = 0, 0
    res = []
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            res.append([s, e])
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1
    return res

def intersect_all(lists):
    if not lists:
        return []
    res = lists[0]
    for lst in lists[1:]:
        res = intersect_two(res, lst)
        if not res:
            break
    return res

