    # busy_intervals: list of (start,end) minutes sorted, within work hours
    free = []
    cur = work_start
    for s, e in sorted(busy_intervals):
        if s > cur:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < work_end:
        free.append((cur, work_end))
    return free

def intersect(intervals1, intervals2):
    i, j = 0, 0
    res = []
    while i < len(intervals1) and j < len(intervals2):
        a1, a2 = intervals1[i]
        b1, b2 = intervals2[j]
        start = max(a1, b1)
        end = min(a2, b2)
        if end - start >= duration:
            res.append((start, end))
        if a2 < b2:
            i += 1
        else:
            j += 1
    return res

def find_slot(allow_avoid):
    for day in days_order:
        if not allow_avoid and day == avoid_day:
            continue
        # collect busy for each participant on this day
