work_start, work_end = to_min('09:00'), to_min('17:00')
duration=30

busy={
    'Daniel':{
        'Monday':[('09:30','10:30'),('12:00','12:30'),('13:00','14:00'),('14:30','15:00'),('15:30','16:00')],
        'Tuesday':[('11:00','12:00'),('13:00','13:30'),('15:30','16:00'),('16:30','17:00')],
        'Wednesday':[('09:00','10:00'),('14:00','14:30')],
        'Thursday':[('10:30','11:00'),('12:00','13:00'),('14:30','15:00'),('15:30','16:00')],
        'Friday':[('09:00','09:30'),('11:30','12:00'),('13:00','13:30'),('16:30','17:00')],
    },
    'Bradley':{
        'Monday':[('09:30','11:00'),('11:30','12:00'),('12:30','13:00'),('14:00','15:00')],
        'Tuesday':[('10:30','11:00'),('12:00','13:00'),('13:30','14:00'),('15:30','16:30')],
        'Wednesday':[('09:00','10:00'),('11:00','13:00'),('13:30','14:00'),('14:30','17:00')],
        'Thursday':[('09:00','12:30'),('13:30','14:00'),('14:30','15:00'),('15:30','16:30')],
        'Friday':[('09:00','09:30'),('10:00','12:30'),('13:00','13:30'),('14:00','14:30'),('15:30','16:30')],
    }
}

# Preferences
avoid_days = {'Daniel':{'Wednesday','Thursday'},
              'Bradley':{'Monday','Friday'}}
# Bradley also cannot meet Tuesday before 12:00
def allowed(person, day, start):
    if day in avoid_days.get(person,set()):
        return False
    if person=='Bradley' and day=='Tuesday' and start<to_min('12:00'):
        return False
    return True

days=['Monday','Tuesday','Wednesday','Thursday','Friday']

def complement(busy_int):
    free=[]
    cur=work_start
    for s,e in sorted(busy_int):
        if s>cur:
            free.append((cur,s))
        cur=max(cur,e)
    if cur<work_end:
        free.append((cur,work_end))
    return free

def intersect(a,b):
    i=j=0
    res=[]
    while i<len(a) and j<len(b):
        s=max(a[i][0],b[j][0])
        e=min(a[i][1],b[j][1])
        if e-s>=duration:
            res.append((s,e))
        if a[i][1]<b[j][1]:
            i+=1
        else:
            j+=1
    return res

# Try to find a slot respecting preferences; if none, relax avoid_days
for relax in [False, True]:
    for day in days:
        # check if day is globally avoided by any participant (when not relaxed)
        if not relax:
            if any(day in avoid_days.get(p,set()) for p in busy):
                continue
        free_lists=[]
        for person in busy:
            ints=[(to_min(s),to_min(e)) for s,e in busy[person].get(day,[])]
            ints+=[(0,work_start),(work_end,24*60)]
            free_lists.append(complement(ints))
        common=free_lists[0]
        for fl in free_lists[1:]:
            common=intersect(common,fl)
            if not common:
                break
        for s,_ in common:
            if all(allowed(p,day,s) for p in busy):
                print([day,to_str(s),to_str(s+duration)])
                raise SystemExit

